mapper.select:
SELECT h.history_id AS history_id, h.admin_id AS admin_id, h.user_id AS user_id, COALESCE(c.care_nm, e.emp_nm) AS user_name, w.ward_nm AS ward_name, h.action_cd AS action_code, h.created_at AS created_at,
CASE WHEN c.caregiver_id IS NOT NULL THEN 'CAREGIVER' WHEN e.emp_id IS NOT NULL THEN 'GENERAL' END AS job_type, NULLIF(REGEXP_REPLACE(cl.location_nm, '[^0-9]', '', 'g'), '') AS room_number, h.action_detail FROM tb_admin_history h LEFT JOIN tb_emp e ON e.hosp_div_id = h.hosp_div_id AND e.emp_id = h.user_id
LEFT JOIN tb_caregiver c ON c.hosp_div_id = h.hosp_div_id AND CONCAT('cg:', c.caregiver_id) = h.user_id LEFT JOIN tb_location cl ON cl.location_id = c.location_id LEFT JOIN tb_ward w ON w.hosp_div_id = h.hosp_div_id AND w.ward_id = COALESCE(cl.ward_id, e.ward_id) WHERE h.hosp_div_id = #{hospitalDomain} ORDER BY h.created_at DESC, h.history_id DESC LIMIT #{limit}
